def same(a,b):
 if type(a)is not type(b):return False
 if isinstance(a,dict):return a.keys()==b.keys()and all(same(a[k],b[k])for k in a)
 if isinstance(a,list):return len(a)==len(b)and all(same(x,y)for x,y in zip(a,b))
 return a==b
def _raw(root,p):
 root=Path(root).resolve();rel=Path(p);assert not rel.is_absolute()and'..'not in rel.parts;f=root/rel;assert f.resolve()==f and f.is_file();return f.read_bytes()
def installed(root):return (Path(root)/REF).is_file()
def proof(root,chapter=None,people=None):
 raw=lambda p:_raw(root,p);load=lambda p:json.loads(raw(p));b=raw(REF);assert hashlib.sha256(b).hexdigest()==SHA;c=json.loads(b);ch=load(CH)
 if chapter is not None:assert same(ch,chapter)
 assert all(ch[k]==v for k,v in c['dimensions'].items())and same(ch['source'],c['source_metadata'])
 assert hashlib.sha256(raw(c['raw_path'])).hexdigest()==c['raw_sha256']
 assert [p['id']for p in ch['paragraphs']]==list(c['paragraphs'])
 ps={p['id']:p for p in ch['paragraphs']};ms={m['id']:(p,m)for p in ch['paragraphs']for m in p['mentions']}
 assert len(ms)==len(c['markers'])
 for pid,v in c['paragraphs'].items():assert ps[pid]['text']==v['text']and hashlib.sha256(ps[pid]['text'].encode()).hexdigest()==v['text_sha256']
 for mid,v in c['markers'].items():
  p,m=ms[mid];assert same({k:x for k,x in m.items()if k!='person_id'},v)and p['text'][m['start']:m['end']]==m['surface']
 if people is None:people={p['id']:p for p in load('registry/persons.json')['persons']}
 roles={}
 for role,seed in c['roles'].items():
  p,m=ms[seed['person_mention_id']];pid=m['person_id'];assert m['kind']=='person'and pid in people;roles[role]=pid
  expected=dict(work_id=ch['work_id'],book_id=ch['book_id'],chapter_id=ch['id'],source_id=ch['source_id'],paragraph_id=p['id'],mention_id=m['id'],quote=m['surface'])
  assert [e for e in people[pid]['evidence']if e.get('mention_id')==m['id']]==[expected]
  assert sum(any(e.get('mention_id')==m['id']for e in x.get('evidence',[]))for x in people.values())==1
  # Non-literal preferred glyphs are owned by the base proof, not invented aliases.
  if 'source_preferred_reading_binding'not in m:assert any(a['surface']==m['surface']and m['id']in a['mention_ids']for a in people[pid]['aliases'])
 def bind(records):
  rows=copy.deepcopy(records)
  for r in rows:
   b=r.get('source_career_role',r.get('source_appointment_context'));assert b['kind']==KIND;r['person_id']=roles[b['role']]
  return rows
 hs=bind(c['expected_holdings']);ds=bind(c['expected_details']);qs=bind(c['expected_proposals']);docs={c['holding_path']:dict(format_version='0.2',record_type='title_holding_assertion_set',chapter_id=ch['id'],holdings=hs),c['detail_path']:dict(format_version='0.2',record_type='biographical_source_detail_set',chapter_id=ch['id'],records=ds)}
 for p,w in docs.items():assert same(load(p),w)
